-- Learning dataset schema.
--
-- GENERATED by tools/generate_dataset.py. Flyway checksums this file, so
-- once it has been applied anywhere it is immutable: change the dataset
-- shape in a new V-numbered migration rather than editing this one.
--
-- Two schemas with identical definitions:
--   learning      every lesson, example and interview problem runs here.
--   learning_alt  the same tables with rows chosen to break naive answers.
--                 Answer evaluation runs a submission against both, so a
--                 query that hardcodes a value from `learning` is caught.
--
-- ${learnerRole} is a Flyway placeholder resolved from configuration. The
-- grants below are the entire set of privileges the playground role ever
-- holds: USAGE on these two schemas and SELECT on these tables. It has no
-- rights at all on the app schema, so a learner cannot read the stored
-- solutions by querying for them.

create schema if not exists learning;
create schema if not exists learning_alt;

-- =========================================================================
--  learning
-- =========================================================================

--  Six departments. One of them deliberately has no employees, so a LEFT JOIN
--  from departments is observably different from an INNER JOIN.
create table learning.departments (
    dept_id        integer       primary key,
    dept_name      text          not null unique,
    location       text,
    budget         numeric(12,2)
);

--  A four-level reporting hierarchy with a NULL manager at the top, one
--  employee with no department, deliberate salary ties, and employees who
--  out-earn their manager.
create table learning.employees (
    emp_id         integer       primary key,
    first_name     text          not null,
    last_name      text          not null,
    email          text          not null unique,
    dept_id        integer       references learning.departments(dept_id),
    manager_id     integer       references learning.employees(emp_id),
    job_title      text          not null,
    salary         numeric(10,2) not null check (salary > 0),
    hire_date      date          not null,
    is_active      boolean       not null default true
);

--  A NULL end_date means the project is still running.
create table learning.projects (
    project_id     integer       primary key,
    project_name   text          not null,
    dept_id        integer       references learning.departments(dept_id),
    start_date     date          not null,
    end_date       date,
    budget         numeric(12,2) not null
);

--  The junction table for the many-to-many between employees and projects.
create table learning.employee_projects (
    emp_id         integer       not null references learning.employees(emp_id),
    project_id     integer       not null references learning.projects(project_id),
    role           text          not null,
    allocation_pct integer       not null check (allocation_pct between 1 and 100),
    primary key (emp_id, project_id)
);

--  A self-referencing hierarchy, three levels deep, for recursive CTEs. One
--  leaf category has no products.
create table learning.categories (
    category_id          integer primary key,
    category_name        text    not null,
    parent_category_id   integer references learning.categories(category_id)
);

--  attributes is JSONB so the JSON lessons have something real to query.
--  Several products were never ordered.
create table learning.products (
    product_id     integer       primary key,
    product_name   text          not null,
    category_id    integer       references learning.categories(category_id),
    unit_price     numeric(10,2) not null check (unit_price >= 0),
    units_in_stock integer       not null default 0,
    discontinued   boolean       not null default false,
    attributes     jsonb
);

--  Two customers have never placed an order, and one contact_name is NULL.
create table learning.customers (
    customer_id    integer  primary key,
    company_name   text     not null,
    contact_name   text,
    country        text     not null,
    city           text,
    signup_date    date     not null,
    segment        text     not null
);

--  A NULL ship_date means the order has not shipped. Statuses include
--  cancelled orders, which most naive revenue queries forget to exclude.
create table learning.orders (
    order_id         integer primary key,
    customer_id      integer not null references learning.customers(customer_id),
    employee_id      integer references learning.employees(emp_id),
    order_date       date    not null,
    ship_date        date,
    status           text    not null,
    shipping_country text    not null
);

--  unit_price is stored per line rather than read from products, because the
--  price at the time of the order is not the price today. Line revenue is
--  quantity * unit_price * (1 - discount).
create table learning.order_items (
    order_id    integer       not null references learning.orders(order_id),
    product_id  integer       not null references learning.products(product_id),
    quantity    integer       not null check (quantity > 0),
    unit_price  numeric(10,2) not null,
    discount    numeric(4,3)  not null default 0 check (discount between 0 and 0.5),
    primary key (order_id, product_id)
);

--  An order can have several partial payments, or none at all.
create table learning.payments (
    payment_id integer       primary key,
    order_id   integer       not null references learning.orders(order_id),
    paid_at    timestamp     not null,
    amount     numeric(10,2) not null,
    method     text          not null
);

--  Deliberately gappy daily activity, for consecutive-date and
--  gaps-and-islands questions.
create table learning.user_activity (
    activity_id   integer primary key,
    customer_id   integer not null references learning.customers(customer_id),
    activity_date date    not null,
    activity_type text    not null
);

--  Append-only status changes. Finding the current status per customer is the
--  latest-record-per-entity pattern.
create table learning.account_status_history (
    history_id     integer   primary key,
    customer_id    integer   not null references learning.customers(customer_id),
    status         text      not null,
    effective_from timestamp not null
);

--  Ninety consecutive days for two regions, for running totals, moving
--  averages and month-over-month growth.
create table learning.daily_sales (
    sale_date date          not null,
    region    text          not null,
    revenue   numeric(12,2) not null,
    primary key (sale_date, region)
);

--  No unique constraint on email, on purpose: this is the table the
--  find-and-remove-duplicates questions operate on.
create table learning.contacts (
    contact_id integer   primary key,
    email      text      not null,
    full_name  text      not null,
    created_at timestamp not null
);

--  Contains ties and both an odd and an even number of rows per subject, so
--  median and percentile answers have to handle both.
create table learning.exam_scores (
    student_id integer not null,
    subject    text    not null,
    score      integer not null check (score between 0 and 100),
    primary key (student_id, subject)
);

